"""JSON 文件持久化的共享存储。

许愿板的所有数据保存在单个 JSON 文件里（列表，按时间先后追加）：

- 进程内并发：threading.Lock 保护；
- 跨进程并发：用 O_CREAT|O_EXCL 独占创建锁文件实现互斥（纯标准库、跨平台）；
- 写盘：先写临时文件再 os.replace 原子替换，进程中途退出也不会损坏数据；
- 读取：list_wishes() 返回最新在前。

对外只暴露 WishStore.add() 与 WishStore.list_wishes()，上层无需关心加锁细节。
"""

from __future__ import annotations

import json
import os
import threading
import time
from datetime import datetime, timezone

MAX_TEXT_LEN = 200


class StorageError(Exception):
    """存储层错误（例如获取文件锁超时、数据文件损坏）。"""


class _FileLock:
    """跨进程互斥锁：独占创建锁文件，退出时删除。"""

    def __init__(self, path: str, timeout: float = 10.0, poll_interval: float = 0.02) -> None:
        self._path = path
        self._timeout = timeout
        self._poll = poll_interval
        self._acquired = False

    def __enter__(self) -> "_FileLock":
        deadline = time.monotonic() + self._timeout
        while True:
            try:
                fd = os.open(self._path, os.O_CREAT | os.O_EXCL | os.O_WRONLY)
            except FileExistsError:
                if time.monotonic() >= deadline:
                    raise StorageError(f"获取文件锁超时: {self._path}") from None
                time.sleep(self._poll)
                continue
            else:
                os.write(fd, str(os.getpid()).encode("ascii"))
                os.close(fd)
                self._acquired = True
                return self

    def __exit__(self, exc_type, exc, tb) -> bool:
        if self._acquired:
            self._acquired = False
            try:
                os.unlink(self._path)
            except FileNotFoundError:
                pass
        return False


def _new_id() -> str:
    """生成不重复的愿望 id（纳秒时间戳 + 随机数）。"""
    return f"{time.time_ns():x}-{os.urandom(4).hex()}"


def _now_iso() -> str:
    return datetime.now(timezone.utc).isoformat(timespec="seconds")


class WishStore:
    """共享许愿板存储：一个 JSON 文件 + 双层锁（进程内线程锁 + 跨进程文件锁）。"""

    def __init__(self, path: str) -> None:
        self.path = os.path.abspath(path)
        self._thread_lock = threading.Lock()
        self._lock_path = self.path + ".lock"
        self._tmp_path = f"{self.path}.{os.getpid()}.tmp"
        # 初始化：确保数据文件存在且是合法的空列表
        with self._thread_lock, _FileLock(self._lock_path):
            if not os.path.exists(self.path):
                self._atomic_write([])

    # ---- 内部方法：调用前必须已持有锁 ----

    def _atomic_write(self, wishes: list) -> None:
        with open(self._tmp_path, "w", encoding="utf-8") as f:
            json.dump(wishes, f, ensure_ascii=False, indent=2)
            f.flush()
            os.fsync(f.fileno())
        os.replace(self._tmp_path, self.path)

    def _read_all(self) -> list:
        try:
            with open(self.path, "r", encoding="utf-8") as f:
                data = json.load(f)
        except FileNotFoundError:
            return []
        except json.JSONDecodeError as exc:
            raise StorageError(f"数据文件损坏: {self.path} ({exc})") from exc
        if not isinstance(data, list):
            raise StorageError(f"数据文件格式错误: {self.path}")
        return data

    # ---- 对外接口 ----

    def add(self, text: str) -> dict:
        """追加一条愿望（上层负责剥离空白，这里做最后校验），返回新增记录。"""
        if not isinstance(text, str) or not text.strip():
            raise ValueError("text 必须是非空字符串")
        if len(text) > MAX_TEXT_LEN:
            raise ValueError(f"text 不能超过 {MAX_TEXT_LEN} 个字符")
        record = {"id": _new_id(), "text": text, "created_at": _now_iso()}
        with self._thread_lock, _FileLock(self._lock_path):
            wishes = self._read_all()
            wishes.append(record)  # 追加到末尾：文件里保持时间先后顺序
            self._atomic_write(wishes)
        return record

    def list_wishes(self) -> list:
        """返回全部愿望，最新的在最前面。"""
        with self._thread_lock, _FileLock(self._lock_path):
            wishes = self._read_all()
        wishes.reverse()  # 文件里最旧在前，读出后反转即最新在前
        return wishes

"""匿名许愿板：仅用 Python 标准库实现的 HTTP 服务。

路由：
    GET  /                 许愿板页面（模板 + 愿望列表 + 底部小诗）
    POST /wish             提交一条愿望（JSON {"text": ...} 或表单编码），成功回 200
                           与更新后的完整页面；文本超过 200 字回 413 与错误页
    GET  /assets/poem.txt  底部小诗原文（text/plain）

安全要点：愿望文本在渲染进 HTML 前经过 html.escape()（GET 渲染与 POST 渲染两条
路径都覆盖）；请求体上限 4KB，防恶意大包。

测试可直接 import build_page / make_server，不必真开端口。
"""

from __future__ import annotations

import argparse
import html
import json
import os
import sys
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer
from urllib.parse import parse_qs

from storage import MAX_TEXT_LEN, StorageError, WishStore

BASE_DIR = os.path.dirname(os.path.abspath(__file__))
TEMPLATE_PATH = os.path.join(BASE_DIR, "templates", "index.html")
POEM_PATH = os.path.join(BASE_DIR, "assets", "poem.txt")
DATA_PATH = os.environ.get("WISHES_PATH", os.path.join(BASE_DIR, "wishes.json"))

REQUEST_BODY_MAX_BYTES = 4096
SERVER_NAME = "WishBoard/1.0"


def render_page(body_html: str, poem_html: str, count: int) -> str:
    """把模板占位符替换为实际内容，返回完整 HTML 字符串。"""
    with open(TEMPLATE_PATH, "r", encoding="utf-8") as f:
        template = f.read()
    return (
        template.replace("<!-- WISH_ITEMS -->", body_html)
        .replace("<!-- POEM -->", poem_html)
        .replace("{{count}}", str(count))
        .replace("{{maxlen}}", str(MAX_TEXT_LEN))
    )


def build_page(store: WishStore, *, escaped: bool = False, poem_path: str = POEM_PATH,
               template_path: str = TEMPLATE_PATH) -> str:
    """渲染完整页面。escaped=True 时对愿望文本做 HTML 转义（服务响应用）。

    测试可直接调用本函数对照两条渲染路径。
    """
    wishes = store.list_wishes()  # 最新在前
    lines = []
    for w in wishes:
        text = html.escape(w["text"], quote=True) if escaped else w["text"]
        lines.append(f'<li class="wish"><span class="wish-text">{text}</span></li>')
    body = "\n".join(lines)
    with open(poem_path, "r", encoding="utf-8") as f:
        poem = f.read()
    return render_page(body, poem, len(wishes))


class _Error(Exception):
    """请求处理中的受控错误，message 直接作为响应正文（纯 ASCII）。"""

    def __init__(self, status: int, message: str, content_type: str = "text/plain; charset=utf-8"):
        super().__init__(message)
        self.status = status
        self.message = message
        self.content_type = content_type


class WishBoardHandler(BaseHTTPRequestHandler):
    server_version = SERVER_NAME
    requestBodyMaxLength = REQUEST_BODY_MAX_BYTES
    store: WishStore = None  # 由 make_server 注入

    # ---- 响应辅助 ----

    def _send_bytes(self, status: int, content_type: str, body: bytes, extra_headers=None) -> None:
        self.send_response(status)
        self.send_header("Content-Type", content_type)
        self.send_header("Content-Length", str(len(body)))
        self.send_header("Cache-Control", "no-store")
        for k, v in (extra_headers or {}).items():
            self.send_header(k, v)
        self.end_headers()
        if self.command != "HEAD":
            self.wfile.write(body)

    def _send_html(self, html_text: str, status: int = 200) -> None:
        self._send_bytes(status, "text/html; charset=utf-8", html_text.encode("utf-8"))

    def _send_json(self, payload: dict, status: int = 200) -> None:
        self._send_bytes(status, "application/json; charset=utf-8",
                         json.dumps(payload, ensure_ascii=False).encode("utf-8"))

    def _redirect(self, location: str) -> None:
        self.send_response(303)
        self.send_header("Location", location)
        self.send_header("Content-Length", "0")
        self.end_headers()

    # ---- 请求体与路由 ----

    def _read_body(self) -> bytes:
        cl = self.headers.get("Content-Length")
        if cl is None:
            raise _Error(411, "Content-Length required")
        try:
            length = int(cl)
        except (TypeError, ValueError):
            raise _Error(400, "invalid Content-Length") from None
        if length < 0:
            raise _Error(400, "invalid Content-Length")
        if length > self.requestBodyMaxLength:
            raise _Error(413, "request body too large")
        return self.rfile.read(length)

    def _parse_wish_text(self, body: bytes) -> str:
        """从 JSON 或表单编码的请求体中提取 text 字段。"""
        content_type = (self.headers.get("Content-Type") or "").split(";", 1)[0].strip().lower()
        if content_type in ("", "application/json"):
            try:
                data = json.loads(body.decode("utf-8"))
            except (UnicodeDecodeError, json.JSONDecodeError):
                raise _Error(400, "invalid JSON body") from None
            if not isinstance(data, dict) or "text" not in data:
                raise _Error(400, "missing field: text")
            text = data["text"]
            if not isinstance(text, str):
                raise _Error(400, "field text must be a string")
            return text.strip()
        if content_type == "application/x-www-form-urlencoded":
            fields = parse_qs(body.decode("utf-8"), keep_blank_values=True)
            if "text" not in fields:
                raise _Error(400, "missing field: text")
            return fields["text"][0].strip()
        raise _Error(415, "unsupported content type, use JSON or form-urlencoded")

    def do_GET(self) -> None:
        path = self.path.split("?", 1)[0]
        if path in ("", "/"):
            self._send_html(build_page(self.store, escaped=True))
        elif path == "/assets/poem.txt":
            try:
                with open(POEM_PATH, "rb") as f:
                    poem = f.read()
            except OSError:
                raise _Error(404, "poem not found") from None
            self._send_bytes(200, "text/plain; charset=utf-8", poem)
        else:
            raise _Error(404, "not found")

    def do_HEAD(self) -> None:
        path = self.path.split("?", 1)[0]
        if path in ("", "/"):
            self._send_html(build_page(self.store, escaped=True))
        elif path == "/assets/poem.txt":
            try:
                with open(POEM_PATH, "rb") as f:
                    poem = f.read()
            except OSError:
                raise _Error(404, "poem not found") from None
            self._send_bytes(200, "text/plain; charset=utf-8", poem)
        else:
            raise _Error(404, "not found")

    def do_POST(self) -> None:
        path = self.path.split("?", 1)[0]
        if path != "/wish":
            raise _Error(404, "not found")
        body = self._read_body()
        text = self._parse_wish_text(body)
        try:
            self.store.add(text)
        except ValueError:
            # 只可能是超长（空串在 _parse_wish_text 前后都到不了这里）：
            # 回 413 + 错误页，data-error="limit" 便于测试与前端定位
            error_page = (
                '<!DOCTYPE html><html lang="en"><head><meta charset="utf-8">'
                "<title>Wish too long</title></head><body>"
                f'<h1>Wish rejected</h1><p>Your wish is longer than '
                f'{MAX_TEXT_LEN} characters.</p>'
                f'<a href="/" data-error="limit">Back to the board</a>'
                f"</body></html>"
            )
            self._send_html(error_page, status=413)
            return
        except StorageError as exc:
            raise _Error(503, f"storage unavailable: {exc}") from None
        # 成功：直接回渲染后的完整页面（无需前端再发一次 GET）
        self._send_html(build_page(self.store, escaped=True))

    # ---- 错误兜底：受控错误输出 JSON/文本，意外异常回 500 且不中断服务 ----

    def handle_one_request(self) -> None:
        try:
            super().handle_one_request()
        except _Error:
            raise
        except Exception:
            self.log_error("unhandled error: %s", sys.exc_info()[1])
            try:
                self._send_json({"error": "internal server error"}, status=500)
            except OSError:
                pass

    def _handle_error(self, exc: _Error) -> None:
        accept = self.headers.get("Accept") or ""
        if exc.status == 404 and "text/html" in accept:
            self._send_html(
                '<!DOCTYPE html><html lang="en"><head><meta charset="utf-8">'
                "<title>Not Found</title></head><body>"
                '<h1>404 Not Found</h1><p>The page you requested does not exist.</p>'
                '<a href="/">Back to the board</a></body></html>',
                status=404,
            )
            return
        self._send_json({"error": exc.message}, status=exc.status)

    def log_message(self, fmt: str, *args) -> None:  # 保持默认输出到 stderr
        sys.stderr.write("%s - - [%s] %s\n" % (self.address_string(), self.log_date_time_string(), fmt % args))


# 把 _Error 的统一处理挂到 do_GET / do_HEAD / do_POST 的异常出口，
# 并过滤掉下划线开头的"属性"，避免 ThreadingHTTPServer 把它们误当方法探测。
def _wrap(handler_method):
    def inner(self):
        try:
            handler_method(self)
        except _Error as exc:
            self._handle_error(exc)
    inner.__name__ = handler_method.__name__
    return inner


for _name in ("do_GET", "do_HEAD", "do_POST"):
    setattr(WishBoardHandler, _name, _wrap(getattr(WishBoardHandler, _name)))
del _name, _wrap


def make_server(host: str = "127.0.0.1", port: int = 0, store: WishStore | None = None,
                data_path: str | None = None) -> ThreadingHTTPServer:
    """构建 HTTP 服务（测试可直接调用，port=0 表示随机端口）。

    data_path： wishing 数据文件路径；测试传 tmp_path 下的文件即可，不碰真实数据。
    """
    if store is None:
        store = WishStore(data_path or DATA_PATH)
    handler = type("BoundWishBoardHandler", (WishBoardHandler,), {"store": store})
    return ThreadingHTTPServer((host, port), handler)


def _parse_args(argv: list | None = None) -> argparse.Namespace:
    parser = argparse.ArgumentParser(description="Anonymous wish board (stdlib only)")
    parser.add_argument("--host", default="127.0.0.1")
    parser.add_argument("--port", type=int, default=8000)
    parser.add_argument("--data", default=None, help="wishes JSON file (default: ./wishes.json)")
    return parser.parse_args(argv)


def main(argv: list | None = None) -> int:
    args = _parse_args(argv)
    data_path = args.data or DATA_PATH
    try:
        store = WishStore(data_path)
        build_page(store, escaped=True)  # 启动前自检：模板、小诗、数据文件可读
    except (StorageError, OSError) as exc:
        print(f"启动失败: {exc}", file=sys.stderr)
        return 1
    server = make_server(args.host, args.port, store=store)
    host, port = server.server_address[:2]
    print(f"Wish board serving on http://{host}:{port}  (data: {os.path.abspath(data_path)})")
    try:
        server.serve_forever()
    except KeyboardInterrupt:
        pass
    finally:
        server.server_close()
    return 0


if __name__ == "__main__":
    sys.exit(main())

